import typer

from pyvkteamsclient.client import DesktopClient


app = typer.Typer(name="pyvkteamsclient")


@app.command("sandbox")
def sandbox_client(
    chat_id: str,
    text: str,
    sandbox_url: str = "stage-stable.v3.im-sandbox.devmail.ru",
):
    with DesktopClient(
        uin="autotest001@autotest.clients",
        fix_otp="ONPREM",
        api_url=f"https://u-{sandbox_url}",
        binary_api_url=f"https://u-{sandbox_url}",
    ) as client:
        client.send_basic_message(sn=chat_id, text=text)


app()
